import React, { useEffect, useMemo, useRef } from "react";
import { createChart, CrosshairMode } from "lightweight-charts";
import { EMA, RSI, MACD } from "technicalindicators";

function generateCandles({ seed, points = 140, startPrice = 1200 }) {
  const candles = [];
  let lastClose = startPrice;
  const startTime = Math.floor(Date.now() / 1000) - points * 60;
  for (let i = 0; i < points; i += 1) {
    const time = startTime + i * 60;
    const rand = Math.sin(seed + i) * 2 + (Math.random() - 0.5) * 3;
    const open = lastClose;
    const close = Math.max(1, open + rand);
    const high = Math.max(open, close) + Math.random() * 3;
    const low = Math.min(open, close) - Math.random() * 3;
    const volume = Math.round(600 + Math.random() * 1200);
    candles.push({ time, open, high, low, close, value: volume }); // "value" is used for volume series
    lastClose = close;
  }
  return candles;
}

function intervalForTimeframe(frame) {
  switch (frame) {
    case "5m": return 300;
    case "15m": return 900;
    case "1D": return 86400;
    case "1W": return 604800;
    default: return 86400;
  }
}

export default function TradingChart({ symbol, timeframe }) {
  const containerRef = useRef(null);
  const chartRef = useRef(null);
  const seriesMap = useRef({});
  const dataRef = useRef([]);

  const activeIndicators = {
    EMA: true,
    RSI: true,
  };

  useEffect(() => {
    if (!containerRef.current) return undefined;

    const chart = createChart(containerRef.current, {
      layout: {
        background: { color: "#131722" },
        textColor: "#d1d4dc",
        fontSize: 12,
      },
      grid: {
        vertLines: { color: "#2a2e39" },
        horzLines: { color: "#2a2e39" },
      },
      crosshair: {
        mode: CrosshairMode.Normal,
      },
      rightPriceScale: {
        borderColor: "#2a2e39",
        autoScale: true,
        scaleMargins: { top: 0.1, bottom: 0.25 },
      },
      timeScale: {
        borderColor: "#2a2e39",
        timeVisible: true,
        secondsVisible: false,
      },
    });

    const candleSeries = chart.addCandlestickSeries({
      upColor: "#26a69a",
      downColor: "#ef5350",
      borderVisible: false,
      wickUpColor: "#26a69a",
      wickDownColor: "#ef5350",
    });

    const volumeSeries = chart.addHistogramSeries({
      color: "#26a69a",
      priceFormat: { type: "volume" },
      priceScaleId: "",
      scaleMargins: { top: 0.8, bottom: 0 },
    });

    chartRef.current = chart;
    seriesMap.current.candles = candleSeries;
    seriesMap.current.volume = volumeSeries;

    function handleResize() {
      if (!containerRef.current || !chart) return;
      chart.applyOptions({
        width: containerRef.current.clientWidth,
        height: containerRef.current.clientHeight,
      });
    }

    const observer = new ResizeObserver(handleResize);
    observer.observe(containerRef.current);

    return () => {
      observer.disconnect();
      chart.remove();
    };
  }, []);

  useEffect(() => {
    if (!chartRef.current || !seriesMap.current.candles) return;

    const seed = symbol.split("").reduce((acc, char) => acc + char.charCodeAt(0), 0);
    const startPrice = 800 + (seed % 400);
    const initialData = generateCandles({ seed, startPrice, points: 140 });

    const interval = intervalForTimeframe(timeframe);
    const baseTime = Math.floor(Date.now() / 1000) - initialData.length * interval;

    const formatted = initialData.map((item, index) => ({
      ...item,
      time: baseTime + index * interval,
    }));

    dataRef.current = formatted;
    const { candles, volume } = seriesMap.current;

    candles.setData(formatted);
    volume.setData(
      formatted.map((d) => ({
        time: d.time,
        value: d.value,
        color: d.close > d.open ? "rgba(38, 166, 154, 0.5)" : "rgba(239, 83, 80, 0.5)",
      }))
    );

    // Indicator Logic
    const closePrices = formatted.map((d) => d.close);
    const chart = chartRef.current;

    // Clean up indicator series
    Object.keys(seriesMap.current).forEach((key) => {
      if (key !== "candles" && key !== "volume" && seriesMap.current[key]) {
        try { chart.removeSeries(seriesMap.current[key]); } catch (e) {}
        delete seriesMap.current[key];
      }
    });

    const mapIndicatorData = (vals) => {
      const result = [];
      const offset = formatted.length - vals.length;
      for (let i = 0; i < vals.length; i++) {
        if (vals[i] != null && !isNaN(vals[i])) {
          result.push({ time: formatted[i + offset].time, value: vals[i] });
        }
      }
      return result;
    };

    if (activeIndicators.EMA) {
      const emaVals = EMA.calculate({ period: 20, values: closePrices });
      const emaSeries = chart.addLineSeries({
        color: "#ff9800",
        lineWidth: 2,
        title: "EMA (20)",
      });
      emaSeries.setData(mapIndicatorData(emaVals));
      seriesMap.current.ema = emaSeries;
    }

    if (activeIndicators.RSI) {
      const rsiVals = RSI.calculate({ period: 14, values: closePrices });
      const rsiSeries = chart.addLineSeries({
        color: "#9c27b0",
        lineWidth: 2,
        title: "RSI (14)",
        priceScaleId: "rsi",
      });
      chart.priceScale("rsi").applyOptions({
        scaleMargins: { top: 0.8, bottom: 0 },
      });
      rsiSeries.setData(mapIndicatorData(rsiVals));
      seriesMap.current.rsi = rsiSeries;
    }

    chart.timeScale().fitContent();
  }, [symbol, timeframe]);

  // Real-time updates effect
  useEffect(() => {
    if (!chartRef.current || !seriesMap.current.candles) return undefined;
    const interval = intervalForTimeframe(timeframe);

    const timer = setInterval(() => {
      const last = dataRef.current[dataRef.current.length - 1];
      if (!last) return;

      const change = (Math.random() - 0.5) * 6;
      const open = last.close;
      const close = Math.max(1, open + change);
      const high = Math.max(open, close) + Math.random() * 2;
      const low = Math.min(open, close) - Math.random() * 2;
      const time = last.time + interval;
      const value = Math.round(600 + Math.random() * 1200);

      const next = { time, open, high, low, close, value };
      dataRef.current = [...dataRef.current.slice(1), next];

      seriesMap.current.candles.update(next);
      seriesMap.current.volume.update({
        time,
        value,
        color: close >= open ? "rgba(38, 166, 154, 0.5)" : "rgba(239, 83, 80, 0.5)",
      });

      // Update indicators if necessary (simplified for simulation)
      // In a real app, you'd recalculate or use a streaming indicator lib
    }, 2500);

    return () => clearInterval(timer);
  }, [symbol, timeframe]);

  return (
    <div 
      className="trading-chart" 
      ref={containerRef} 
      style={{ width: "100%", height: "100%", position: "relative" }} 
    />
  );
}
